mapper.select:
	select distinct m.id, m.parent_id, m.menu_name, m.route_path, m.vue_component_path, m.route_name, m.visible, m.status, ifnull(m.perms,'') as perms, m.menu_type, m.icon, m.order_num, m.create_time
	from sys_menu m
	left join sys_role_menu rm on m.id = rm.menu_id
	left join sys_user_role ur on rm.role_id = ur.role_id
	left join sys_role ro on ur.role_id = ro.role_id
		where ur.user_id = #{userId}

            AND m.menu_name like concat('%', #{menu.menuName}, '%')


            AND m.visible = #{menu.visible}


            AND m.status = #{menu.status}

	order by m.parent_id, m.order_num
